def modal():
    return '''<dialog id="request" aria-labelledby="request-title"><div class="row"><h2 id="request-title">Ariza qoldirish</h2><button class="close" data-close aria-label="Yopish">×</button></div><p class="muted">Demo ariza uchun ma’lumotlarni kiriting.</p><form id="request-form"><label for="request-name">Ismingiz</label><input id="request-name" name="name" autocomplete="given-name" required maxlength="80" placeholder="Ismingizni yozing"><label for="request-phone">Telefon raqamingiz</label><input id="request-phone" name="phone" type="tel" autocomplete="tel" required maxlength="24" inputmode="tel" placeholder="+998 90 123 45 67"><label for="request-message">Xabaringiz yoki savolingiz <span class="fine">(ixtiyoriy)</span></label><textarea id="request-message" name="message" rows="3" maxlength="1000" placeholder="Qisqacha yozing…"></textarea><div class="dialog-actions"><button class="btn" type="submit">Ariza tayyorlash →</button><button class="btn secondary" type="button" data-close>Bekor qilish</button></div><p class="result" id="request-result" role="status"></p></form><p class="fine" style="margin:20px 0 0">Dizayn namunasidagi forma. Ma’lumotlar yuborilmaydi.</p></dialog>'''

def nav(logo, links, action):
    return f'''<header class="shell"><nav class="nav" aria-label="Asosiy menyu"><a class="logo" href="#">{logo}</a><button class="menu-button" aria-expanded="false" aria-controls="navlinks">Menyu ☰</button><div class="navlinks" id="navlinks">{''.join(f'<a href="{url}">{text}</a>' for url,text in links)}{action}</div></nav></header>'''

def footer(name):
    return f'''<footer class="foot"><div class="shell row"><span>© 2026 {name} · Dizayn namunasidir</span><a href="index.html">← Barcha shablonlar</a></div></footer>'''

def page(filename,title,style,body,extra='',fonts=()):
    style += {'01-kasblab.html': '.lesson-bottom{align-items:center;gap:12px;flex-wrap:wrap}.learning-art{min-width:0}.achievement{position:static;margin:16px 0 0;box-shadow:none}.browser-card{padding:20px}.learn-hero h1{font-size:clamp(38px,5.3vw,68px)}@media(max-width:420px){.learning-art{padding:16px}.browser-card{padding:16px}.lesson-card{padding:18px}.study-row{flex-wrap:wrap}.study-row span:last-child{margin-left:43px!important}.learn-cta{padding:24px}.learn-cta h2{font-size:28px}}', '02-samar.html': '.art-caption{background:#203f32;color:#fff;padding:8px 12px;border-radius:4px;max-width:calc(100% - 40px)}.travel-card{display:flex;flex-direction:column}.travel-card .travel-info{flex:1}@media(max-width:420px){.travel-hero h1{font-size:42px}.travel-quote{padding:24px}}', '03-orbit.html': '.project-info{align-items:flex-start;flex-wrap:wrap}.studio-hero h1{font-size:clamp(38px,8.5vw,110px);overflow-wrap:normal}@media(max-width:420px){.studio-hero h1{font-size:clamp(38px,11.5vw,48px);letter-spacing:-1.8px}.service-item h3{font-size:23px}.studio-cta h2{font-size:32px}.art-bottom{font-size:10px}}', '04-forma.html': '.add-cart{width:44px;height:44px;min-height:44px;flex-shrink:0}.product{display:flex;flex-direction:column}.product-info{flex:1;display:flex;flex-direction:column}.product-info>.row{margin-top:auto}.shop-benefits{line-height:1.7}.collection-stamp{color:#536557}.cart-counter{min-width:22px;height:22px;font-size:12px}@media(max-width:420px){.shop-copy{padding:28px 22px}.shop-benefits{grid-template-columns:1fr;text-align:left;font-size:12px}.collection-note h2{font-size:30px}}', '05-pulseboard.html': '.sidebar,.side-links{min-width:0}.dashboard{grid-template-columns:220px minmax(0,1fr)}.chart-card,.order-card{display:block}.chart-card>.row{flex-wrap:wrap;align-items:start}.periods{flex-shrink:0}.periods button{font-size:12px;min-width:48px}.dash-top{flex-wrap:wrap}.profile{flex-shrink:0}.metric .trend{font-size:12px}.chart-labels,.status,th,.side-label,.demo-pill{font-size:12px}.side-links a{min-height:44px;display:flex;align-items:center}.table-wrap:focus-visible{outline-offset:2px}.chart-svg{height:240px;min-height:160px}.dash-footer{font-size:12px}.dash-charts{grid-template-columns:minmax(0,1.7fr) minmax(0,1fr)}.order-search{min-height:44px;font-size:14px}@media(max-width:1200px){.workspace .grid4{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:1100px){.dashboard{grid-template-columns:180px minmax(0,1fr)}.dash-charts{grid-template-columns:minmax(0,1fr)}}@media(max-width:680px){.dashboard{grid-template-columns:minmax(0,1fr)}.side-links{scrollbar-width:thin}}@media(max-width:420px){.workspace .grid4{grid-template-columns:minmax(0,1fr)}.metric b{font-size:28px}}'}.get(filename, "")
    font_links=''.join(f'<link rel="stylesheet" href="assets/fonts/{font}.css">' for font in fonts)
    doc=f'''<!doctype html><html lang="uz"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{title} — dizayn namunasi</title><link rel="stylesheet" href="shared.css">{font_links}<style>{style}</style></head><body><a class="skip" href="#main">Asosiy mazmunga o‘tish</a>{body}{modal()}{extra}<div class="toast" role="status" hidden></div><script src="shared.js"></script></body></html>'''
