style=''' :root{--bg:#f6f2e9;--surface:#fffcf6;--ink:#25372e;--muted:#56675b;--accent:#2c5c46;--wash:#e6ede2;--line:#dce0d4;--radius:3px}.logo{font-family:Georgia,serif;font-weight:400;font-size:29px}.travel-hero{display:grid;grid-template-columns:1fr 1.1fr;gap:40px;align-items:center;padding:45px 0 68px}.travel-hero h1{font:clamp(48px,5.9vw,78px)/1.06 Georgia,serif;letter-spacing:-2px;margin:20px 0 28px}.travel-hero h1 em{font-weight:400;color:#a06943}.travel-hero p{max-width:395px;color:var(--muted)}.travel-actions{display:flex;gap:24px;align-items:center;margin:30px 0}.travel-label{font-size:12px;border-left:2px solid #bb9268;padding-left:14px;margin-top:40px}.travel-art{background:#ddd0b8;border-radius:180px 180px 2px 2px;overflow:hidden;position:relative}.travel-art svg{width:100%;height:auto}.art-caption{position:absolute;bottom:18px;left:22px;color:#fef8ed;font-size:11px;font-weight:600}.travel-strip{display:flex;justify-content:space-between;border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:23px 0;gap:20px;font-size:12px}.travel-strip b{font-size:17px;margin-right:8px}.destination-visual{height:190px;position:relative;overflow:hidden;background:#ded2bb}.destination-visual:before{content:"";position:absolute;left:50%;bottom:0;width:125px;height:155px;transform:translateX(-50%);background:#bd916b;border-radius:65px 65px 0 0;border:12px solid #d8b48c}.destination-visual:after{content:"";position:absolute;left:50%;bottom:0;width:63px;height:107px;transform:translateX(-50%);background:#2e686a;border-radius:33px 33px 0 0;border:5px solid #9dc1bb}.destination:nth-child(2) .destination-visual{background:#bdd0c9}.destination:nth-child(2) .destination-visual:before{background:#428886;border-color:#78b0ac}.destination:nth-child(3) .destination-visual{background:#e4cbb2}.destination:nth-child(3) .destination-visual:before{height:175px;width:90px;border-radius:0;border-color:#c0a382;background:#ead7b8}.destination{border:1px solid var(--line);background:var(--surface)}.destination-copy{padding:24px}.destination h3{font:26px Georgia,serif;margin:12px 0}.destination p{font-size:13px;color:var(--muted);min-height:43px}.destination .row{font-size:12px;border-top:1px solid var(--line);padding-top:17px}.travel-quote{background:#e7ebdf;padding:45px;display:grid;grid-template-columns:.7fr 1.4fr;gap:50px}.travel-quote h2{font:38px Georgia,serif;margin-bottom:18px}.travel-quote blockquote{margin:0;font:25px/1.5 Georgia,serif}.travel-quote .fine{margin-top:20px}@media(max-width:800px){.travel-hero{grid-template-columns:1fr;padding:30px 0 40px}.travel-art{max-width:530px}.travel-strip{flex-wrap:wrap;justify-content:start}.travel-quote{grid-template-columns:1fr;gap:20px;padding:28px}.travel-quote blockquote{font-size:22px}}'''
art='''<svg viewBox="0 0 540 530" role="img" aria-label="Samarqand me’morchiligidan ilhomlangan chizma"><rect width="540" height="530" fill="#ded0b5"/><circle cx="411" cy="100" r="45" fill="#efe3ca"/><path d="M0 395Q100 365 195 390T540 380V530H0Z" fill="#c0b093"/><rect x="59" y="215" width="32" height="225" fill="#b99872"/><rect x="61" y="199" width="28" height="20" fill="#598581"/><path d="M58 199Q75 170 92 199" fill="#4b7777"/><rect x="448" y="215" width="32" height="225" fill="#b99872"/><rect x="450" y="199" width="28" height="20" fill="#598581"/><path d="M447 199Q464 170 481 199" fill="#4b7777"/><rect x="107" y="292" width="326" height="148" fill="#cbb08a"/><rect x="168" y="163" width="204" height="277" fill="#b48b61"/><rect x="180" y="178" width="180" height="262" fill="#79a39a"/><rect x="193" y="191" width="154" height="249" fill="#ccad7d"/><path d="M206 440V300Q206 232 270 211Q334 232 334 300V440" fill="#346667"/><path d="M222 440V305Q222 256 270 235Q318 256 318 305V440" fill="#284d4e"/><path d="M237 440V313Q237 277 270 261Q303 277 303 313V440" fill="#182f36"/><g fill="#416e6a"><path d="M119 405V353Q119 333 139 323Q159 333 159 353V405Z"/><path d="M381 405V353Q381 333 401 323Q421 333 421 353V405Z"/></g><g stroke="#c8d5b8" stroke-width="2" opacity=".7"><path d="M182 183L358 438M358 183L182 438M185 205L355 205M185 225L355 225M185 245L355 245"/></g><path d="M0 440H540V530H0Z" fill="#8d8067"/><path d="M220 440L127 530M320 440L410 530M0 467H540M0 502H540" stroke="#b6a78c" stroke-width="2"/><g fill="#4b6550"><ellipse cx="36" cy="398" rx="30" ry="65"/><ellipse cx="510" cy="398" rx="26" ry="57"/></g></svg>'''
body=nav('samar<span>.</span>',[('#manzillar','Manzillar'),('#sayohat','Sayohatlar'),('#hikoya','Bizning hikoya')],'<button class="btn small" data-request="Sayohatni rejalashtirish">Sayohatni rejalashtirish ↗</button>')+f'''<main id="main"><section class="shell travel-hero"><div><p class="eyebrow">Samarqandni yangidan kashf eting</p><h1>Har bir ko‘cha —<br><em>bir hikoya.</em></h1><p>Moviy gumbazlar, qadimiy maydonlar va samimiy insonlar. Samarqandni shunchaki ko‘rmang — uning hikoyasini his qiling.</p><div class="travel-actions"><a class="btn" href="#manzillar">Sayohatni boshlash ↗</a><span class="fine">Mahalliy gidlar bilan</span></div><div class="travel-label">REGISTON MAYDONI<br><span class="muted">Buyuk Ipak yo‘lining yuragida</span></div></div><div class="travel-art">{art}<span class="art-caption">01 / Samarqand · Me’moriy illyustratsiya</span></div></section><div class="shell travel-strip"><span><b>2 750</b> yillik tarix</span><span><b>40+</b> diqqatga sazovor maskan</span><span><b>12</b> mahalliy gid</span><span><b>4.9</b> sayohatchilar bahosi</span></div><section class="shell section" id="manzillar"><div class="section-head"><div><p class="eyebrow">Esda qoladigan manzillar</p><h2 style="font-family:Georgia,serif;font-weight:400">Qayerdan boshlaymiz?</h2></div><p>Har bir manzilning o‘z ruhi bor. Sizga mos sayohatni tanlang.</p></div><div class="grid3" id="sayohat">'''
for title,desc,duration,price in [('Registon va eski shahar','Me’morchilik, hunarmandchilik va qadimiy ko‘chalardan hikoyalar.','3 soat','180 000'),('Shohi Zinda yo‘llari','Moviy koshinlar orasida tarix va san’at bilan uchrashuv.','2 soat','140 000'),('Samarqand ta’mlari','Mahalliy bozor, tandir non va osh tayyorlash an’analari.','4 soat','250 000')]:
    body+=f'<article class="destination"><div class="destination-visual" aria-hidden="true"></div><div class="destination-copy"><span class="eyebrow" style="font-size:10px">{duration} · Mahalliy gid</span><h3>{title}</h3><p>{desc}</p><div class="row"><b>{price} so‘mdan</b><button class="btn small" data-request="{title} sayohatiga ariza">Tanlash →</button></div></div></article>'
body+='''</div></section><section class="shell section" style="padding-top:0" id="hikoya"><div class="travel-quote"><div><p class="eyebrow">Sayohat xotiralari</p><h2>Manzil emas,<br>taassurot.</h2></div><div><blockquote>“Mahalliy gid bilan shahar butunlay boshqacha ochildi. Har bir binoning ortida biz bilmagan ajoyib hikoya bor ekan.”</blockquote><p class="fine">Dilnoza · namunaviy sayohatchi fikri</p><button class="btn" data-request="Shaxsiy sayohat rejasi">O‘z sayohatimni rejalashtirish ↗</button></div></div></section></main>'''+footer('Samar')
page('02-samar.html','02 · Samar',style,body)

# 03 — dark technology studio, large typography and geometric poster.
style=''' :root{--bg:#101411;--surface:#181e19;--ink:#eef2e9;--muted:#96a193;--accent:#c0f26c;--on-accent:#152009;--wash:#26311e;--line:#30382e;--radius:2px}.nav{border-bottom:1px solid var(--line)}.logo{font-size:27px;letter-spacing:1px}.studio-hero{padding:60px 0 30px}.studio-top{display:flex;justify-content:space-between;gap:35px}.studio-hero h1{font-size:clamp(56px,8.5vw,110px);letter-spacing:-5px;margin:22px 0 30px;font-weight:650;line-height:.98}.studio-hero h1 span{color:var(--accent)}.studio-intro{display:flex;justify-content:space-between;align-items:end;gap:36px}.studio-intro p{color:var(--muted);max-width:425px;margin:0}.orbit-art{height:330px;margin:40px 0 0;background:#c0f26c;position:relative;overflow:hidden;display:flex;align-items:center;justify-content:center;color:#172212}.orbit-art svg{width:700px;height:320px}.art-stamp{position:absolute;left:24px;top:22px;font-size:11px;letter-spacing:2px;font-weight:700}.art-bottom{position:absolute;bottom:20px;right:24px;font:12px ui-monospace,monospace}.studio-services{display:grid;grid-template-columns:1fr 2fr;gap:60px}.service-list{border-top:1px solid var(--line)}.service-item{padding:24px 0;border-bottom:1px solid var(--line);display:grid;grid-template-columns:35px 1fr;gap:20px}.service-item span{color:var(--accent);font-size:12px}.service-item h3{font-size:26px;font-weight:500;margin-bottom:10px}.service-item p{color:var(--muted);font-size:14px;max-width:490px;margin:0}.project-poster{height:210px;display:flex;align-items:center;justify-content:center;background:#303b2b;position:relative;overflow:hidden}.project-poster b{font-size:45px;letter-spacing:-2px}.project-card:nth-child(2) .project-poster{background:#d7d7c7;color:#172212}.project-card:nth-child(3) .project-poster{background:#606b57}.project-poster:after{content:"";position:absolute;width:180px;height:180px;border:1px solid #a4bb7f55;border-radius:50%;right:-70px;top:-60px}.project-info{padding:20px 0}.project-info h3{font-size:20px;margin:0}.studio-cta{border-top:1px solid var(--line);padding:55px 0;display:flex;justify-content:space-between;gap:25px;align-items:center}.studio-cta h2{font-size:clamp(35px,5vw,60px);margin:0;letter-spacing:-2px}@media(max-width:800px){.studio-hero{padding-top:30px}.studio-hero h1{letter-spacing:-2.7px}.studio-intro{align-items:start;flex-direction:column}.studio-services{grid-template-columns:1fr;gap:25px}.studio-cta{align-items:start;flex-direction:column}.orbit-art{height:230px}.orbit-art svg{height:220px}.studio-top .fine{display:none}}'''
body=nav('ORBIT<span>®</span>',[('#xizmatlar','Xizmatlar'),('#ishlar','Ishlar'),('#aloqa','Aloqa')],'<button class="btn small" data-request="Loyihani muhokama qilish">Keling, gaplashamiz ↗</button>')+'''<main id="main"><section class="shell studio-hero"><div class="studio-top"><p class="eyebrow">Mustaqil raqamli studiya / 2026</p><span class="fine">SAMARQAND, UZBEKISTAN</span></div><h1>G‘oyani<br><span>ta’sirga</span> aylantiramiz.</h1><div class="studio-intro"><p>Strategiya, dizayn va texnologiya. Biz odamlar foydalanishni xohlaydigan raqamli mahsulotlar yaratamiz.</p><a class="btn" href="#ishlar">Tanlangan ishlar ↗</a></div><div class="orbit-art"><span class="art-stamp">IDEAS IN MOTION</span><svg viewBox="0 0 700 320" aria-hidden="true"><g fill="none" stroke="#243119" stroke-width="1.5"><ellipse cx="350" cy="160" rx="290" ry="90" transform="rotate(-25 350 160)"/><ellipse cx="350" cy="160" rx="290" ry="90" transform="rotate(25 350 160)"/><ellipse cx="350" cy="160" rx="135" ry="145"/><circle cx="350" cy="160" r="74"/><path d="M45 160H655M350 12V308" opacity=".3"/></g><circle cx="350" cy="160" r="49" fill="#243119"/><circle cx="112" cy="233" r="11" fill="#243119"/><circle cx="557" cy="249" r="7" fill="#243119"/><circle cx="403" cy="46" r="8" fill="#243119"/></svg><span class="art-bottom">STRATEGY × DESIGN × CODE</span></div></section><section class="shell section studio-services" id="xizmatlar"><div><p class="eyebrow">01 / Nima qilamiz</p><h2 style="font-size:38px">Oddiy ko‘rinadi.<br>Puxta ishlaydi.</h2></div><div class="service-list"><div class="service-item"><span>01</span><div><h3>Veb-sayt va platformalar</h3><p>Brendingizni tushuntiradigan va mijozni kerakli harakatga olib boradigan saytlar.</p></div></div><div class="service-item"><span>02</span><div><h3>Mahsulot dizayni</h3><p>Murakkab jarayonlar uchun tushunarli interfeys va foydalanuvchiga qulay tajriba.</p></div></div><div class="service-item"><span>03</span><div><h3>Brend va vizual uslub</h3><p>G‘oyangizni esda qoladigan shakl, rang va aniq ovoz bilan ifodalaymiz.</p></div></div></div></section><section class="shell section" style="padding-top:0" id="ishlar"><div class="section-head"><div><p class="eyebrow">02 / Tanlangan ishlar</p><h2>Natija gapirsin.</h2></div><span class="fine">Namunaviy portfolio</span></div><div class="filters" aria-label="Ishlarni filtrlash"><button class="filter active" data-filter="all" aria-pressed="true">Barchasi</button><button class="filter" data-filter="web" aria-pressed="false">Veb-sayt</button><button class="filter" data-filter="brand" aria-pressed="false">Brending</button></div><div class="grid3"><article class="project-card" data-category="web"><div class="project-poster"><b>KASB.</b></div><div class="row project-info"><h3>Ta’lim platformasi</h3><span class="fine">Veb-sayt</span></div></article><article class="project-card" data-category="brand"><div class="project-poster"><b>terra</b></div><div class="row project-info"><h3>Terra identikasi</h3><span class="fine">Brending</span></div></article><article class="project-card" data-category="web"><div class="project-poster"><b>moliya+</b></div><div class="row project-info"><h3>Moliyaviy xizmat</h3><span class="fine">Veb-sayt</span></div></article></div></section><section class="shell studio-cta" id="aloqa"><h2>Keyingi katta g‘oya<br>sizniki bo‘lsin.</h2><button class="btn" data-request="Yangi loyiha bo‘yicha ariza">Loyihani boshlash ↗</button></section></main>'''+footer('Orbit Studio')
page('03-orbit.html','03 · Orbit',style,body)

# 04 — clean retail catalog with geometric product art and real cart.
style=''' :root{--bg:#fff;--surface:#fff;--ink:#27323b;--muted:#596771;--accent:#254f70;--wash:#eaf0f4;--line:#e3e7e9;--radius:4px}.shop-banner{background:#273d4a;color:#f5f7f9;text-align:center;padding:9px 18px;font-size:11px}.logo{font:32px Georgia,serif}.shop-hero{display:grid;grid-template-columns:.85fr 1.3fr;min-height:380px;background:#edf1f2}.shop-copy{padding:58px 46px}.shop-copy h1{font:clamp(40px,4.8vw,61px)/1.08 Georgia,serif;margin:18px 0 20px;letter-spacing:-1.8px}.shop-copy p{color:var(--muted);font-size:14px;max-width:340px;margin-bottom:28px}.shop-art{position:relative;display:flex;align-items:center;justify-content:center;background:#dfe7e8;overflow:hidden}.shop-art svg{width:440px;height:380px}.shop-art .fine{position:absolute;bottom:22px;right:24px}.shop-benefits{display:grid;grid-template-columns:repeat(3,1fr);padding:22px 0;border-bottom:1px solid var(--line);font-size:12px;text-align:center;gap:12px}.product-image{height:240px;background:#f1f3f4;display:grid;place-items:center;position:relative;overflow:hidden}.product-image svg{width:170px;height:200px}.product:nth-child(2) .product-image{background:#edece7}.product:nth-child(3) .product-image{background:#eaf0ef}.product:nth-child(4) .product-image{background:#f0ece8}.product-image .tag{position:absolute;top:13px;left:13px;background:#fff;color:var(--ink)}.product-info{padding:16px 0}.product h3{font-size:15px;font-weight:600;margin:0 0 5px}.product-info .fine{margin-bottom:12px}.product-price{font-size:14px;font-weight:750}.add-cart{display:grid;place-items:center;border:1px solid var(--line);background:white;color:var(--ink);width:33px;height:33px;border-radius:50%;font-size:21px}.add-cart:hover{background:var(--accent);color:white}.collection-note{display:grid;grid-template-columns:1fr 1fr;background:#edf1ee;padding:40px;gap:40px;align-items:center}.collection-note h2{font:36px Georgia,serif}.collection-note p{color:var(--muted);font-size:14px;max-width:410px}.collection-stamp{height:150px;border:1px solid #c2cfc5;display:grid;place-items:center;font:40px Georgia,serif;color:#718275}.cart-item{display:flex;align-items:center;justify-content:space-between;gap:15px;border-bottom:1px solid var(--line);padding:14px 0;font-size:14px}.remove{background:transparent;color:#934343;font-size:12px}.cart-total{padding-top:20px;margin-top:10px}.cart-counter{display:inline-flex;align-items:center;justify-content:center;background:var(--accent);color:white;border-radius:50%;font-size:10px;height:18px;min-width:18px;margin-left:4px}@media(max-width:800px){.shop-hero{grid-template-columns:1fr}.shop-copy{padding:32px 28px}.shop-art{height:270px}.shop-art svg{height:280px}.shop-benefits{font-size:10px}.collection-note{grid-template-columns:1fr;padding:28px;gap:15px}.product-image{height:220px}}'''
chair='''<svg viewBox="0 0 440 380" role="img" aria-label="Yog‘och kreslo illyustratsiyasi"><ellipse cx="230" cy="330" rx="140" ry="18" fill="#cad5d6"/><path d="M140 310L160 204M293 310L279 204" stroke="#937550" stroke-width="15"/><path d="M178 235L166 329M263 235L280 329" stroke="#a58861" stroke-width="13"/><path d="M142 180Q142 110 216 100Q284 95 292 171L293 212H144Z" fill="#607e80"/><path d="M149 176Q149 115 214 108Q273 102 282 172" fill="none" stroke="#81999a" stroke-width="3"/><path d="M138 207Q212 181 299 202L304 231Q224 256 135 231Z" fill="#46666a"/><path d="M117 155L115 245M319 155L320 245M114 167L151 179M282 179L320 167" stroke="#a58861" stroke-width="13" stroke-linecap="round"/></svg>'''
body='<div class="shop-banner">Yangi kolleksiya · 500 000 so‘mdan yuqori buyurtmalarga bepul yetkazish</div>'+nav('forma<span>.</span>',[('#mahsulotlar','Katalog'),('#kolleksiya','Kolleksiya'),('#yetkazish','Yetkazish')],'<button class="btn secondary small" data-open-cart>Savat <span class="cart-counter" data-cart-count>0</span></button>')+f'''<main id="main"><section class="shell shop-hero"><div class="shop-copy"><p class="eyebrow">Yashash uchun yaratilgan</p><h1>Uyingizga<br>osoyishtalik<br>olib keling.</h1><p>Tabiiy materiallar. Puxta ishlangan shakllar. Kundalik hayotingizga mos buyumlar.</p><a class="btn" href="#mahsulotlar">Kolleksiyani ko‘rish ↗</a></div><div class="shop-art">{chair}<span class="fine">Forma Chair / 2026</span></div></section><div class="shell shop-benefits" id="yetkazish"><span>↗ O‘zbekiston bo‘ylab yetkazish</span><span>◇ Tabiiy materiallar</span><span>↺ 14 kun ichida qaytarish</span></div><section class="shell section" id="mahsulotlar"><div class="section-head"><div><p class="eyebrow">Tanlangan buyumlar</p><h2 style="font-family:Georgia,serif;font-weight:400">Oddiy. Chiroyli. Sizniki.</h2></div><span class="fine" data-product-count aria-live="polite">4 ta mahsulot</span></div><div class="filters" aria-label="Mahsulotlarni filtrlash"><button class="filter active" data-filter="all" aria-pressed="true">Barchasi</button><button class="filter" data-filter="furniture" aria-pressed="false">Mebel</button><button class="filter" data-filter="decor" aria-pressed="false">Dekor</button></div><div class="grid4">'''
products=[('Forma kreslo','Eman yog‘ochi · tabiiy mato',1290000,'furniture',chair),('Terra vaza','Qo‘lda ishlangan keramika',180000,'decor','<svg viewBox="0 0 170 200" aria-hidden="true"><ellipse cx="85" cy="176" rx="46" ry="8" fill="#d7d3ca"/><path d="M69 34H101V70Q131 95 126 138Q122 170 85 173Q48 170 44 138Q39 95 69 70Z" fill="#b68d68"/><ellipse cx="85" cy="34" rx="16" ry="5" fill="#806447"/><path d="M72 80Q56 100 56 129" stroke="#d6b799" stroke-width="3" fill="none"/></svg>'),('Luma chiroq','Sokin yorug‘lik · metall',420000,'decor','<svg viewBox="0 0 170 200" aria-hidden="true"><ellipse cx="85" cy="181" rx="41" ry="6" fill="#d5ded9"/><path d="M85 84V166" stroke="#45615e" stroke-width="6"/><ellipse cx="85" cy="172" rx="32" ry="6" fill="#45615e"/><path d="M53 41H117L137 91H33Z" fill="#c9bfa7"/><ellipse cx="85" cy="91" rx="52" ry="7" fill="#b4a990"/></svg>'),('Linea stol','Ixcham shakl · yong‘oq yog‘ochi',690000,'furniture','<svg viewBox="0 0 170 200" aria-hidden="true"><ellipse cx="85" cy="174" rx="66" ry="8" fill="#ddd3c8"/><path d="M43 91L35 168M125 91L135 168M74 106L72 176" stroke="#8c6950" stroke-width="8"/><ellipse cx="85" cy="86" rx="62" ry="20" fill="#ba9272"/><path d="M23 85V94Q85 128 147 94V85Q85 116 23 85" fill="#997559"/></svg>')]
for title,desc,price,category,svg in products:
    body+=f'<article class="product" data-category="{category}"><div class="product-image"><span class="tag">Yangi</span>{svg}</div><div class="product-info"><h3>{title}</h3><p class="fine">{desc}</p><div class="row"><span class="product-price">{price:,} so‘m</span><button class="add-cart" aria-label="{title}ni savatga qo‘shish" data-add="{title}" data-price="{price}">+</button></div></div></article>'.replace(f'{price:,}',f'{price:,}'.replace(',',' '))
body+='''</div></section><section class="shell section" style="padding-top:0" id="kolleksiya"><div class="collection-note"><div><p class="eyebrow">Kamroq, lekin yaxshiroq</p><h2>Har bir buyumning<br>o‘z o‘rni bor.</h2><p>Biz trend ortidan quvmaymiz. Uzoq vaqt xizmat qiladigan, sodda va sifatli buyumlarni tanlaymiz.</p><a class="btn secondary" href="#mahsulotlar">Buyumlarni tanlash →</a></div><div class="collection-stamp" aria-hidden="true">made for living.</div></div></section></main>'''+footer('Forma')
cart='<dialog id="cart" aria-labelledby="cart-title"><div class="row"><h2 id="cart-title">Savatingiz</h2><button class="close" data-close aria-label="Savatni yopish">×</button></div><p class="muted" id="cart-empty">Hozircha savat bo‘sh. Katalogdan buyum tanlang.</p><div id="cart-items"></div><div class="row cart-total"><b>Jami</b><b id="cart-total">0 so‘m</b></div><p class="fine" style="margin-top:24px">Demo savat. To‘lov yoki haqiqiy buyurtma amalga oshirilmaydi.</p><button class="btn" data-close>Katalogga qaytish</button></dialog>'
